if (-not (Get-Command Invoke-Hook -ErrorAction SilentlyContinue)) { . (Join-Path $PSScriptRoot '_HookHarness.ps1') }
$scripts=(Resolve-Path (Join-Path $PSScriptRoot '..\..\scripts')).Path
$ps=Join-Path $scripts 'warehouse-map-check.ps1'
function Put($p,$t){$d=Split-Path -Parent $p;if($d){New-Item -ItemType Directory -Force $d|Out-Null};[IO.File]::WriteAllText($p,$t,[Text.UTF8Encoding]::new($false))}
function Fixture([bool]$Warehouse=$true){$r=Join-Path ([IO.Path]::GetTempPath()) ('warehouse-map-'+[guid]::NewGuid());New-Item -ItemType Directory -Force $r|Out-Null;if($Warehouse){Put (Join-Path $r 'warehouse/DimCustomer.sql') 'CREATE TABLE dw.DimCustomer (CustomerKey int, EffectiveFrom date, IsCurrent bit);';Put (Join-Path $r 'warehouse/usp_LoadCustomer.sql') 'CREATE PROC etl.usp_LoadCustomer @BatchId int AS SELECT 1;'};$r}
function Check($r,$exit,$text){$p=RunArg $ps $r;Assert ($p.Exit-eq$exit) "ps exit $($p.Exit): $($p.Out)";Assert ($p.Out-match$text) "ps missing $text`: $($p.Out)"}
Reset-Tests
It 'non-warehouse and excluded generated/vendor signals are not applicable' {$r=Fixture $false;try{Put (Join-Path $r 'VENDOR/warehouse/DimDecoy.sql') 'CREATE TABLE dw.DimDecoy (IsCurrent bit);';Put (Join-Path $r 'BUILD/warehouse/usp_LoadDecoy.sql') 'CREATE PROC etl.usp_LoadDecoy @BatchId int AS SELECT 1;';Check $r 0 'not-applicable';$missing=Join-Path $r 'missing-root';$p=RunArg $ps $missing;Assert ($p.Exit-eq 2) "PowerShell missing root exit=$($p.Exit)"}finally{Remove-Item -Recurse -Force $r}}
It 'warehouse without map fails' {$r=Fixture;try{Check $r 1 'missing';New-Item -ItemType Directory -Force (Join-Path $r 'docs/warehouse-map.md')|Out-Null;Check $r 1 'missing'}finally{Remove-Item -Recurse -Force $r}}
It 'a scoped write keeps the last full pass''s staleness' {$r=Fixture;try{Start-Sleep -Milliseconds 1100;$t=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ');Put (Join-Path $r 'docs/warehouse-map.md') "<!-- warehouse-map full pass: $t -->`n# map";Check $r 0 'current';Start-Sleep -Milliseconds 1100;Put (Join-Path $r 'warehouse/FactSale.sql') 'CREATE TABLE dw.FactSale (BatchId int);';Check $r 1 'stale';Start-Sleep -Milliseconds 1100;Put (Join-Path $r 'docs/warehouse-map.md') "<!-- warehouse-map full pass: $t -->`n# map`n| dw.FactSale | fact |";Check $r 1 'stale';Start-Sleep -Milliseconds 1100;$t2=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ');Start-Sleep -Milliseconds 1100;Put (Join-Path $r 'docs/warehouse-map.md') "<!-- warehouse-map full pass: $t2 -->`n# map";Check $r 0 'current'}finally{Remove-Item -LiteralPath $r -Recurse -Force -ErrorAction SilentlyContinue}}
It 'a map no full pass has written stays stale' {$r=Fixture;try{Start-Sleep -Milliseconds 1100;Put (Join-Path $r 'docs/warehouse-map.md') "<!-- warehouse-map full pass: none -->`n# map";Check $r 1 'stale \(no full pass yet\)'}finally{Remove-Item -LiteralPath $r -Recurse -Force -ErrorAction SilentlyContinue}}
It 'the remedy names /map-warehouse only where that skill is installed' {$r=Fixture $false;try{Put (Join-Path $r 'azure-pipelines.yml') 'trigger: none';Put (Join-Path $r 'load.sql') 'SELECT @BatchId;';$p=RunArg $ps $r;Assert ($p.Exit-eq1-and$p.Out-match'missing') "no-skill fixture: exit=$($p.Exit) $($p.Out)";Assert ($p.Out-notmatch'/map-warehouse') "no-skill remedy names a skill that is not installed: $($p.Out)";Assert ($p.Out-match'inspect the live schema') "no-skill remedy: $($p.Out)";Put (Join-Path $r 'docs/warehouse-map.md') "<!-- warehouse-map full pass: none -->`n# map";$p=RunArg $ps $r;Assert ($p.Exit-eq1-and$p.Out-match'stale \(no full pass yet\)'-and$p.Out-notmatch'/map-warehouse') "no-skill stale remedy: exit=$($p.Exit) $($p.Out)";Remove-Item -LiteralPath (Join-Path $r 'docs/warehouse-map.md') -Force;Put (Join-Path $r '.claude/skills/map-warehouse/SKILL.md') 'skill';$p=RunArg $ps $r;Assert ($p.Exit-eq1-and$p.Out-match'run /map-warehouse') "skill present, remedy must name it: exit=$($p.Exit) $($p.Out)"}finally{Remove-Item -LiteralPath $r -Recurse -Force -ErrorAction SilentlyContinue}}
It 'current and stale maps are distinguished without unrelated JSON false positives' {$r=Fixture;try{Start-Sleep -Milliseconds 1100;Put (Join-Path $r 'docs/warehouse-map.md') '# map';Check $r 0 'current';Start-Sleep -Milliseconds 1100;Put (Join-Path $r 'package.json') '{"version":"2"}';Check $r 0 'current';Put (Join-Path $r 'warehouse/FactSale.sql') 'CREATE TABLE dw.FactSale (BatchId int);';Check $r 1 'stale'
    $probe=Join-Path $r 'probe';New-Item -ItemType Directory -Force $probe|Out-Null
    Copy-Item -LiteralPath (Join-Path $scripts 'warehouse-signals.tsv') -Destination $probe
    $probePs=Join-Path $probe 'warehouse-map-check.ps1';$psText=[IO.File]::ReadAllText($ps);$psBroken=$psText.Replace('try { $matched = $file.Name -match $parts[1] -or (Select-String -LiteralPath $file.FullName -Pattern $parts[1] -Quiet -ErrorAction Stop) }',"try { throw 'simulated read failure' }");Assert ($psBroken-ne$psText) 'PowerShell read-failure mutation missed';Put $probePs $psBroken
    $p=RunArg $probePs $r;$pText=$p.Out+"`n"+$p.Err;Assert ($p.Exit-eq 2-and$pText-match'Could not read warehouse artifact') "PowerShell artifact read failure was not explicit: exit=$($p.Exit) $pText"
    Copy-Item -LiteralPath $ps -Destination $probePs -Force;Put (Join-Path $probe 'warehouse-signals.tsv') "broken-only-one-field`n"
    $p=RunArg $probePs $r;Assert($p.Exit-eq2)"PowerShell malformed signal exit=$($p.Exit)"
}finally{Remove-Item -Recurse -Force $r}}
# A OneDrive folder carries the ReparsePoint attribute with no LinkType (seen on this host's OneDrive root), and skipping on the bare attribute
# reported every warehouse under it as not-applicable. No test can give a folder that attribute without a filter driver, so the skip's
# predicate is asserted from the source beside the behaviour that must stay: a junction into the repository is still skipped.
It 'a junction is skipped for being a link, not for carrying the reparse attribute' {$r=Fixture $false;$outside=Join-Path ([IO.Path]::GetTempPath()) ('warehouse-outside-'+[guid]::NewGuid());try{Put (Join-Path $outside 'DimCustomer.sql') 'CREATE TABLE dw.DimCustomer (CustomerKey int, EffectiveFrom date, IsCurrent bit);';Put (Join-Path $outside 'usp_LoadCustomer.sql') 'CREATE PROC etl.usp_LoadCustomer @BatchId int AS SELECT 1;';$null=cmd.exe /d /c mklink /J (Join-Path $r 'warehouse') $outside;Assert ((Get-Item -LiteralPath (Join-Path $r 'warehouse')).LinkType-eq'Junction') 'fixture junction was not created';Check $r 0 'not-applicable';$text=[IO.File]::ReadAllText($ps);Assert ($text-match"LinkType -in @\('SymbolicLink', 'Junction'\)") 'the enumeration must skip by LinkType';Assert ($text-notmatch'Attributes -band \[IO\.FileAttributes\]::ReparsePoint') 'the enumeration still skips on the bare ReparsePoint attribute, which OneDrive folders carry'}finally{$null=cmd.exe /d /c rmdir (Join-Path $r 'warehouse');Remove-Item -Recurse -Force $r;Remove-Item -Recurse -Force $outside -ErrorAction SilentlyContinue}}
exit (Write-TestSummary 'WarehouseMapCheck.Tests')
